def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def parse_amount(token: str) -> int:
        if token and token.isascii() and token.isdigit():
            return int(token)
        return -1

    for i, op in enumerate(ops):
        tokens = op.split(" ")
        if "" in tokens:
            rejected.append(i)
            continue

        verb = tokens[0]
        n_tokens = len(tokens)

        if verb == "open":
            if n_tokens != 3:
                rejected.append(i)
                continue
            acct = tokens[1]
            amount = parse_amount(tokens[2])
            if amount < 0 or acct in balances:
                rejected.append(i)
                continue
            balances[acct] = amount
            history.append(("open", acct))

        elif verb == "deposit":
            if n_tokens != 3:
                rejected.append(i)
                continue
            acct = tokens[1]
            amount = parse_amount(tokens[2])
            if amount <= 0 or acct not in balances:
                rejected.append(i)
                continue
            balances[acct] += amount
            history.append(("deposit", acct, amount))

        elif verb == "withdraw":
            if n_tokens != 3:
                rejected.append(i)
                continue
            acct = tokens[1]
            amount = parse_amount(tokens[2])
            if (
                amount <= 0
                or acct not in balances
                or acct in frozen
                or balances[acct] < amount
            ):
                rejected.append(i)
                continue
            balances[acct] -= amount
            history.append(("withdraw", acct, amount))

        elif verb == "transfer":
            if n_tokens != 4:
                rejected.append(i)
                continue
            src, dst = tokens[1], tokens[2]
            amount = parse_amount(tokens[3])
            if (
                amount <= 0
                or src == dst
                or src not in balances
                or dst not in balances
                or src in frozen
                or balances[src] < amount
            ):
                rejected.append(i)
                continue
            balances[src] -= amount
            balances[dst] += amount
            history.append(("transfer", src, dst, amount))

        elif verb == "freeze":
            if n_tokens != 2:
                rejected.append(i)
                continue
            acct = tokens[1]
            if acct not in balances or acct in frozen:
                rejected.append(i)
                continue
            frozen.add(acct)
            history.append(("freeze", acct))

        elif verb == "unfreeze":
            if n_tokens != 2:
                rejected.append(i)
                continue
            acct = tokens[1]
            if acct not in balances or acct not in frozen:
                rejected.append(i)
                continue
            frozen.remove(acct)
            history.append(("unfreeze", acct))

        elif verb == "undo":
            if n_tokens != 1 or not history:
                rejected.append(i)
                continue
            entry = history.pop()
            kind = entry[0]
            if kind == "open":
                del balances[entry[1]]
            elif kind == "deposit":
                balances[entry[1]] -= entry[2]
            elif kind == "withdraw":
                balances[entry[1]] += entry[2]
            elif kind == "transfer":
                balances[entry[1]] += entry[3]
                balances[entry[2]] -= entry[3]
            elif kind == "freeze":
                frozen.remove(entry[1])
            elif kind == "unfreeze":
                frozen.add(entry[1])

        else:
            rejected.append(i)

    return balances, rejected
